/**
 * AIF-C01 cards (issue #225, design §3 / §4.2 / §4.3).
 *
 * The exam mixes two profiles, so this file mixes two card kinds:
 *
 *   concept   Domains 1–3 (AI/ML fundamentals, GenAI fundamentals, applications
 *             of FMs) and the service-identification parts of domains 4–5
 *             (Guardrails, Clarify, Model Cards, Macie, Config, Artifact …).
 *             One card = one unit. `confusables` are the neighbouring terms a
 *             learner mixes up, written to serve as distractors.
 *   framework Domains 4–5 (responsible AI, security / governance), built on two
 *             AWS-published structures rather than an invented taxonomy:
 *             1. AWS Well-Architected Responsible AI Lens (2025-11-19).
 *                perspective = the responsible AI dimension a best practice
 *                serves (the Lens names 10: controllability, privacy, security,
 *                safety, veracity, robustness, fairness, explainability,
 *                transparency, governance; the aws.amazon.com/ai/responsible-ai
 *                page still groups them as 8, see source.note), and
 *                stage = the Lens's own focus area (Use case → Monitoring).
 *                Both axes come from the Lens itself; the choice of which best
 *                practices become cells is editorial, for task coverage. A
 *                best practice that serves no single dimension is filed under
 *                "Cross-cutting".
 *             2. Generative AI (AI) Security Scoping Matrix.
 *                perspective = its five security disciplines, stage = its
 *                scopes (1 consumer app … 5 self-trained model). Scope groups
 *                ("Scopes 1–2" etc.) follow how the page itself groups advice.
 *
 * Sources: definitions follow the text of the AWS page in `source.url`, read on
 * the mining date (2026-10-19). Where the page shows a newer state than the exam
 * guide (renames, "no longer open to new customers", end-of-support notices),
 * that is recorded in `source.note`; the card still describes the capability
 * the exam guide names. `misconceptions` / `confusables` are anti-patterns the
 * text warns about or that follow directly from it.
 *
 * Human review required before relying on these for published questions.
 */

const V = '2026-10-19';
const BR = 'https://docs.aws.amazon.com/bedrock/latest/userguide';
const SM = 'https://docs.aws.amazon.com/sagemaker/latest/dg';
const AC = 'https://docs.aws.amazon.com/bedrock-agentcore/latest/devguide';
const RAI = 'https://docs.aws.amazon.com/wellarchitected/latest/responsible-ai-lens';
const GAL = 'https://docs.aws.amazon.com/wellarchitected/latest/generative-ai-lens';

const NOTE_CLOSED = (svc) => `${svc} は ${V} 時点のドキュメントで「no longer open to new customers」（既存顧客は継続利用可、新機能の予定なし）と表示されている。試験ガイドが名前を挙げているため概念として残す。`;

function src(title, url, note) {
  return note ? { title, url, verifiedAt: V, note } : { title, url, verifiedAt: V };
}

/** concept card helper: one card = one unit */
function concept(id, term, service, definition, confusables, tasks, source) {
  const card = { id: `aif-concept-${id}`, kind: 'concept', term, definition, confusables, tasks, level: 'foundational', source };
  if (service) card.service = service;
  return card;
}

function cell(id, perspective, stage, capability, summary, misconceptions, tasks) {
  return { id, perspective, stage, capability, summary, misconceptions, tasks };
}

